import sec1 from '../img/sec/01.jpg';
import sec2 from '../img/sec/02.jpg';
import sec3 from '../img/sec/03.jpg';
import sec4 from '../img/sec/04.jpg';

// import React, { Component } from "react";
import Slider from "react-slick";




export default function SimpleSlider() {
  var settings = {
    dots: true,
    infinite: true,
    speed: 5000,
    slidesToShow: 1,
    slidesToScroll: 1
  };
  return (
    <Slider {...settings}>
      <div>
        <h3>
<img src={sec1} alt="" />
        </h3>
      </div>
      <div>
        <h3>2</h3>
      </div>
      <div>
        <h3>3</h3>
      </div>
      <div>
        <h3>4</h3>
      </div>
      <div>
        <h3>5</h3>
      </div>
      <div>
        <h3>6</h3>
      </div>
    </Slider>
  );
}
